import{_ as i,o as a,c as e,a3 as t}from"./chunks/framework.IHUN2c1F.js";const c=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"developers/getting-started.md","filePath":"developers/getting-started.md"}'),n={name:"developers/getting-started.md"};function l(h,s,o,d,p,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><p>s32 <strong>1.3.46</strong> speaks protocol 4. One line installs it; no download page, and no <code>sudo</code> for the CLI itself.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;=https&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tlsv1.2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>The script picks the right build (Apple Silicon or Intel), checks the download against <code>SHA256SUMS</code> from the same release, and installs <code>s32</code> into <code>~/.local/bin</code>. libusb is built in; there is nothing else to install.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;=https&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tlsv1.2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>The script installs <code>s32</code> into <code>~/.local/bin</code> and needs <code>libusb-1.0</code> from your distribution. If it is missing, the script stops before it downloads anything and prints the command for your system (<code>sudo apt-get install libusb-1.0-0</code> on Debian and Ubuntu, <code>sudo dnf install libusb1</code> on Fedora).</p><p>It then asks, at your terminal, whether to install the USB rule that lets <code>s32</code> reach the S32 without root. Answer <code>y</code> and it runs <code>sudo</code> for exactly three commands: it copies the rule to <code>/etc/udev/rules.d/99-s32-editor.rules</code>, reloads the rules and triggers udev. Any other answer, or no terminal (a script or an agent), runs no <code>sudo</code> at all: the script prints the same three commands for you to run. It keeps its copy of the rule in <code>~/.local/share/s32/99-s32-editor.rules</code>, and the printed commands point there.</p><p>Unplug the S32 and plug it back in after the rule is installed. Without the rule, <code>--usb</code> needs root.</p><p>The rule gives the logged-in desktop user access to VID/PID <code>0483:a56e</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;0483&quot;, ATTR{idProduct}==&quot;a56e&quot;, TAG+=&quot;uaccess&quot;</span></span></code></pre></div><p>Don&#39;t use <code>MODE=&quot;0666&quot;</code> on a shared machine: whoever opens the interface controls the S32.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>In PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Shik</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tech</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">releases</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">download</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>On an older Windows PowerShell 5.1 (Windows 10 1607 or earlier, Windows 8.1), if the line fails with a TLS or &quot;could not create SSL/TLS secure channel&quot; error, run <code>[Net.ServicePointManager]::SecurityProtocol = &#39;Tls12&#39;</code> first and then the <code>irm</code> line again.</p><p>From a script or an AI agent (no one at the window), run it as one command that returns the installer&#39;s result, so a failed install is not reported as success:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoProfile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Command </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex; exit $LASTEXITCODE&#39;</span></span></code></pre></div><p>The single quotes matter: they stop the calling shell (PowerShell 7, Git Bash, a CI step) from expanding <code>$LASTEXITCODE</code> before <code>powershell</code> runs, which would turn a failed install into exit code 0. From <code>cmd.exe</code>, which does not treat single quotes as quotes, use double quotes instead:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">powershell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -NoProfile -Command </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex; exit $LASTEXITCODE&quot;</span></span></code></pre></div><p>The script installs <code>s32.exe</code> and its DLLs into <code>%LOCALAPPDATA%\\Programs\\s32</code> and adds that folder to your user <code>PATH</code> (no administrator needed). Open a new terminal, or use the same window, and run <code>s32 --version</code>. If <code>s32.exe</code> is running, close it and run the line again.</p><h2 id="path-upgrade-and-versions" tabindex="-1">PATH, upgrade and versions <a class="header-anchor" href="#path-upgrade-and-versions" aria-label="Permalink to &quot;PATH, upgrade and versions&quot;">​</a></h2><ul><li>On macOS and Linux the script never edits a shell file. If <code>~/.local/bin</code> is not on your <code>PATH</code>, it prints the line to add and the file it belongs in. If another <code>s32</code> comes first on your <code>PATH</code>, it warns you with both locations and the other version.</li><li>Run the same line again to upgrade. It prints <code>s32 &lt;old&gt; -&gt; &lt;new&gt; installed in &lt;folder&gt;</code>, or <code>s32 &lt;version&gt; reinstalled</code> when you already have the latest.</li><li>To install a specific version, set <code>S32_VERSION</code> (<code>S32_VERSION=1.3.45</code> before <code>sh</code>, or <code>sh -s -- --version 1.3.45</code> after the pipe; on Windows <code>$env:S32_VERSION=&#39;1.3.45&#39;</code> before the line). A pin may go back to an older release.</li><li><code>S32_INSTALL_DIR</code> changes the install folder. On Windows it must be a full path and a folder that holds nothing else: the installer replaces the whole folder, so it stops with <code>has other files</code> instead of touching a folder that has files of yours.</li><li>Supported: macOS (Apple Silicon and Intel), Linux x86_64, Windows x64. On anything else the script stops with a link to the manual install below.</li></ul><p>Each script is a release asset with its SHA-256 listed in <code>SHA256SUMS</code>: download it and read it first if you prefer.</p><h2 id="manual-install" tabindex="-1">Manual install <a class="header-anchor" href="#manual-install" aria-label="Permalink to &quot;Manual install&quot;">​</a></h2><p>Download the archive for your machine from <a href="https://github.com/Shik-Tech/S32-CLI/releases" target="_blank" rel="noreferrer">S32-CLI Releases</a>.</p><p>macOS: <code>s32-*-darwin-arm64.tar.gz</code> (Apple Silicon) or <code>s32-*-darwin-x64.tar.gz</code> (Intel). libusb is built in. Download only the one for your Mac, so the wildcard below matches a single file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s32-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-darwin-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/s32</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Linux: <code>s32-*-linux-x64.tar.gz</code> holds the binary and the udev rule.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s32-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-x64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/s32</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libusb-1.0-0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Debian / Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sudo dnf install libusb1                 # Fedora</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 99-s32-editor.rules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/udev/rules.d/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udevadm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reload-rules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udevadm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span></span></code></pre></div><p>Windows: unzip <code>s32-*-windows-x64.zip</code> into a folder of its own and put that folder on your <code>PATH</code>. Keep the DLLs from the zip next to <code>s32.exe</code>.</p><p>The install folder belongs to the s32 CLI. The one-line installer replaces the whole folder on an upgrade, so it refuses (<code>has other files</code>, changing nothing) when the folder holds anything that is not part of the s32 CLI: a file from the release zip, or a file listed in the <code>.s32-install</code> list that an earlier one-line install wrote. A manual install does not write that list, so do not unzip into a shared folder such as your <code>bin</code> folder. Move the s32 CLI to an empty folder, or to the default <code>%LOCALAPPDATA%\\Programs\\s32</code>, before you run the one-line installer.</p><h2 id="first-commands" tabindex="-1">First commands <a class="header-anchor" href="#first-commands" aria-label="Permalink to &quot;First commands&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ping</span></span></code></pre></div><p>Without an S32 plugged in, the s32 CLI uses its built-in simulator (<a href="./connecting">Connect</a>). <code>hello</code> prints the protocol and firmware versions, the serial number and the S32&#39;s limits.</p><h2 id="help-and-completion" tabindex="-1">Help and completion <a class="header-anchor" href="#help-and-completion" aria-label="Permalink to &quot;Help and completion&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # the overview</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # arguments, keys and examples of one command</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> completion bash)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Tab completion (zsh: s32 completion zsh)</span></span></code></pre></div><p>See <a href="./commands/session#help">Session</a> for the help pages, <a href="./commands/session#exit-codes">exit codes</a> and <code>-q</code>.</p><h2 id="interactive-session" tabindex="-1">Interactive session <a class="header-anchor" href="#interactive-session" aria-label="Permalink to &quot;Interactive session&quot;">​</a></h2><p>Run <code>s32</code> with no command (or <code>s32 repl</code>) to keep the connection open:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --usb repl</span></span>
<span class="line"><span>s32&gt; list</span></span>
<span class="line"><span>s32&gt; pull internal 1 /tmp/p.s32p</span></span>
<span class="line"><span>s32&gt; quit</span></span></code></pre></div>`,42)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
